--
-- Table structure for table `annual_project_report_items`
--

DROP TABLE IF EXISTS `annual_project_report_items`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `annual_project_report_items` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `import_batch_id` bigint DEFAULT NULL,
  `academic_year` int NOT NULL,
  `strategy` varchar(255) DEFAULT NULL,
  `plan_name` text,
  `objective` text,
  `kpi` text,
  `project_code` varchar(100) DEFAULT NULL,
  `project_name` text NOT NULL,
  `activity_name` text,
  `row_type` enum('project','activity') NOT NULL DEFAULT 'project',
  `parent_item_id` bigint DEFAULT NULL,
  `responsible_person` varchar(255) DEFAULT NULL,
  `sort_order` int DEFAULT '0',
  `raw_row_json` json DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_report_item_year` (`academic_year`),
  KEY `idx_report_item_project_code` (`project_code`),
  KEY `idx_report_item_row_type` (`row_type`),
  KEY `idx_report_item_parent` (`parent_item_id`),
  KEY `idx_report_item_batch` (`import_batch_id`),
  CONSTRAINT `fk_report_item_batch` FOREIGN KEY (`import_batch_id`) REFERENCES `report_import_batches` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_report_item_parent` FOREIGN KEY (`parent_item_id`) REFERENCES `annual_project_report_items` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=445 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

